 readme=cat/key/'README.md';text=readme.read_text();text=text.split('\n## Independent verification — 2026-11-08')[0];text=text.replace('17-Modern-JS-Modules-Tooling/final','18-forkify/final').replace('addition-rnn','mnist');text+='\n## Independent verification — 2026-11-08\n\nBuild status: **'+status+'**. '
